FROM PART F0_0) F1_0)),
temp_view_4 AS (
SELECT /*+ materialize */ F0_1.S_SUPPKEY AS S_SUPPKEY
FROM SUPPLIER F0_1
WHERE (F0_1.S_COMMENT LIKE '%Customer%Complaints%')),
temp_view_5 AS (
