WHERE (F0_1.S_COMMENT LIKE '%Customer%Complaints%')),
temp_view_2 AS (
SELECT /*+ materialize */ F0_0.PS_PARTKEY AS PS_PARTKEY, F0_0.PS_SUPPKEY AS PS_SUPPKEY, F0_0.PS_AVAILQTY AS PS_AVAILQTY, F0_0.PS_SUPPLYCOST AS PS_SUPPLYCOST, F0_0.PS_COMMENT AS PS_COMMENT, F0_0.P_PARTKEY AS P_PARTKEY, F0_0.P_NAME AS P_NAME, F0_0.P_MFGR AS P_MFGR, F0_0.P_BRAND AS P_BRAND, F0_0.P_TYPE AS P_TYPE, F0_0.P_SIZE AS P_SIZE, F0_0.P_CONTAINER AS P_CONTAINER, F0_0.P_RETAILPRICE AS P_RETAILPRICE, F0_0.P_COMMENT AS P_COMMENT, F0_0.PROV_PARTSUPP_PS__PARTKEY AS PROV_PARTSUPP_PS__PARTKEY, F0_0.PROV_PARTSUPP_PS__SUPPKEY AS PROV_PARTSUPP_PS__SUPPKEY, F0_0.PROV_PART_P__PARTKEY AS PROV_PART_P__PARTKEY, F0_0.left__RESULT_TID AS left__RESULT_TID, F0_0.left__SETPROV_DUP_COUNT AS left__SETPROV_DUP_COUNT, F1_0."NESTING_EVAL_1" AS "NESTING_EVAL_1", F1_0.PROV_SUPPLIER_S__SUPPKEY AS PROV_SUPPLIER_S__SUPPKEY, F1_0.right__RESULT_TID AS right__RESULT_TID, F1_0.right__SETPROV_DUP_COUNT AS right__SETPROV_DUP_COUNT, hash(F0_0.left__RESULT_TID, F1_0.right__RESULT_TID) AS _RESULT_TID, GREATEST(F0_0.left__SETPROV_DUP_COUNT, F1_0.right__SETPROV_DUP_COUNT) AS _SETPROV_DUP_COUNT
FROM (
SELECT F0_0.PS_PARTKEY AS PS_PARTKEY, F0_0.PS_SUPPKEY AS PS_SUPPKEY, F0_0.PS_AVAILQTY AS PS_AVAILQTY, F0_0.PS_SUPPLYCOST AS PS_SUPPLYCOST, F0_0.PS_COMMENT AS PS_COMMENT, F0_0.P_PARTKEY AS P_PARTKEY, F0_0.P_NAME AS P_NAME, F0_0.P_MFGR AS P_MFGR, F0_0.P_BRAND AS P_BRAND, F0_0.P_TYPE AS P_TYPE, F0_0.P_SIZE AS P_SIZE, F0_0.P_CONTAINER AS P_CONTAINER, F0_0.P_RETAILPRICE AS P_RETAILPRICE, F0_0.P_COMMENT AS P_COMMENT, F0_0.PROV_PARTSUPP_PS__PARTKEY AS PROV_PARTSUPP_PS__PARTKEY, F0_0.PROV_PARTSUPP_PS__SUPPKEY AS PROV_PARTSUPP_PS__SUPPKEY, F0_0.PROV_PART_P__PARTKEY AS PROV_PART_P__PARTKEY, F0_0._RESULT_TID AS left__RESULT_TID, F0_0._SETPROV_DUP_COUNT AS left__SETPROV_DUP_COUNT
FROM (SELECT * FROM temp_view_3) F0_0) F0_0, LATERAL (
